pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(c));
        vm.assume(amount != 0);
        // wide domain: deliberately no upper bound on amount so overflow-triggering
        // deposits are inside the admissible space
        vm.deal(actor, amount);
        uint256 before = c.getBalance(actor);
        vm.prank(actor);
        bool ok;
        try c.addToBalance{value: amount}() { ok = true; } catch { ok = false; }
        uint256 afterB = c.getBalance(actor);
        // Rule: any SUCCESSFUL deposit must record exactly old+amount (no wrap,
        // no truncation); a wrap must have caused a revert instead.
        assertTrue(!ok || afterB == before + amount);
    }
}

